import { Vector3 } from './Vector3.js';
const corners = Array.from({ length: 8 }, () => new Vector3());
export class Box3 {
    min = new Vector3(Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY);
    max = new Vector3(Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY);
    constructor(min, max) { if (min)
        this.min.copy(min); if (max)
        this.max.copy(max); }
    set(min, max) { this.min.copy(min); this.max.copy(max); return this; }
    copy(value) { return this.set(value.min, value.max); }
    clone() { return new Box3().copy(this); }
    makeEmpty() { this.min.set(Infinity, Infinity, Infinity); this.max.set(-Infinity, -Infinity, -Infinity); return this; }
    isEmpty() { return this.max.x < this.min.x || this.max.y < this.min.y || this.max.z < this.min.z; }
    expandByPoint(point) { this.min.min(point); this.max.max(point); return this; }
    expandByScalar(value) { this.min.addScalar(-value); this.max.addScalar(value); return this; }
    expandByBox(box) { this.min.min(box.min); this.max.max(box.max); return this; }
    setFromArray(values) {
        this.makeEmpty();
        for (let i = 0; i < values.length; i += 3)
            this.expandByPoint(new Vector3(values[i] ?? 0, values[i + 1] ?? 0, values[i + 2] ?? 0));
        return this;
    }
    getCenter(target = new Vector3()) { return this.isEmpty() ? target.set(0, 0, 0) : target.addVectors(this.min, this.max).multiplyScalar(0.5); }
    getSize(target = new Vector3()) { return this.isEmpty() ? target.set(0, 0, 0) : target.subVectors(this.max, this.min); }
    containsPoint(point) { return point.x >= this.min.x && point.x <= this.max.x && point.y >= this.min.y && point.y <= this.max.y && point.z >= this.min.z && point.z <= this.max.z; }
    containsBox(box) { return this.min.x <= box.min.x && box.max.x <= this.max.x && this.min.y <= box.min.y && box.max.y <= this.max.y && this.min.z <= box.min.z && box.max.z <= this.max.z; }
    intersectsBox(box) { return !(box.max.x < this.min.x || box.min.x > this.max.x || box.max.y < this.min.y || box.min.y > this.max.y || box.max.z < this.min.z || box.min.z > this.max.z); }
    clampPoint(point, target = new Vector3()) { return target.copy(point).clamp(this.min, this.max); }
    distanceToPoint(point) { return this.clampPoint(point, corners[0]).distanceTo(point); }
    translate(offset) { this.min.add(offset); this.max.add(offset); return this; }
    applyMatrix4(matrix) {
        if (this.isEmpty())
            return this;
        const min = this.min.clone();
        const max = this.max.clone();
        corners[0].set(min.x, min.y, min.z).applyMatrix4(matrix);
        corners[1].set(min.x, min.y, max.z).applyMatrix4(matrix);
        corners[2].set(min.x, max.y, min.z).applyMatrix4(matrix);
        corners[3].set(min.x, max.y, max.z).applyMatrix4(matrix);
        corners[4].set(max.x, min.y, min.z).applyMatrix4(matrix);
        corners[5].set(max.x, min.y, max.z).applyMatrix4(matrix);
        corners[6].set(max.x, max.y, min.z).applyMatrix4(matrix);
        corners[7].set(max.x, max.y, max.z).applyMatrix4(matrix);
        this.makeEmpty();
        for (const corner of corners)
            this.expandByPoint(corner);
        return this;
    }
}